def validar_torre_poste(Nr_TI: str, Nr_TUC: str, Nr_A1: str, linha: str):
    TIs_LT_LD = {"24","25","26","27","28","29","35","36","37","38","39","55","56","57",
                 "58","59","60","61","62","63","64"}
    if Nr_TI not in TIs_LT_LD and Nr_TUC == "255" and Nr_A1 == "2":
