            adicionar_erro(
                                "COD_ITEM",
                                (
                                    "COD_ITEM deve ser preenchido "
                                    f"quando Cd_NG é {cd_ng}."
                                ),
                                cod_item
                            )

        if str(flg_oat) == "0":

            if str(cd_atip or "0").strip() != "0":
                adicionar_erro(
                                    "Cd_ATIP",
                                    (
                                        "Cd_ATIP deve ser zero "
                                        "quando FLG_OAT é 0."
                                    ),
                                    cd_atip
                                )

        elif str(flg_oat) == "1":

            try:
                cd_atip_int = int(
                                        str(cd_atip).strip()
                                    )
            except (TypeError, ValueError):
                cd_atip_int = None

            if cd_atip_int not in range(1, 11):
                adicionar_erro(
                                    "Cd_ATIP",
                                    (
                                        "Cd_ATIP deve estar entre "
                                        "1 e 10 quando FLG_OAT é 1."
                                    ),
                                    cd_atip
                                )

        tucagem_incompleta = (
                                esta_vazio(nr_tuc)
                                or any(
                                    esta_vazio(atributo)
                                    for atributo in nr_atributos
                                )
                            )

        if (
                str(cd_ng) == "1"
                and tucagem_incompleta
            ):
            campos_tucagem = [
                                "Nr_TUC",
                                "Nr_A1",
                                "Nr_A2",
                                "Nr_A3",
                                "Nr_A4",
                                "Nr_A5",
                                "Nr_A6"
                            ]

            for campo in campos_tucagem:
                valor = obter(campo)

                if esta_vazio(valor):
                    adicionar_erro(
                                        campo,
                                        (
                                            "Tucagem obrigatória "
                                            "quando Cd_NG é 1."
                                        ),
                                        valor
                                    )

        if erros:
            raise ValidationError.from_exception_data(
                                                        cls.__name__,
                                                        erros
                                                    )

        return result

