def converter_decimal(valor, campo):
            if esta_vazio(valor):
                return 0.0

            try:
                return float(
                                str(valor).strip().replace(",", ".")
                            )

            except (TypeError, ValueError):
                adicionar_erro(
                                    campo,
                                    f"Valor decimal inválido: {valor!r}",
                                    valor
                                )
                return None

