            if re.fullmatch(r"1232\d0\d05", cc):
                motivos.append(f"Cd_CC={cc} (veículos)")

            if motivos and tp_bem != "4":
                raise ValueError(
                    f"Id_SEQ_INC={linha}: TP_BEM esperava-se ser 4 "
                    f"quando houver enquadramento em "
